--Cell 1 UEs:
FIRST_UE_SA_CELL_1 = 1
END_UD_SA_CELL_1 = 221

IMSI_1 = 21645400


for UEID = FIRST_UE_SA_CELL_1, END_UD_SA_CELL_1 do
    exec('set_ue simulated id='..UEID..' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 opc_key=0ED47545168EAFE2C39C075829A7B61F nia=null+zuc nea=null sec_key=0102030405060708090A0B0C0D0EFF00  mode=nr enb=2 cell=1 suci=0:311:489:0000:0:0:0'.. IMSI_1 + UEID - 1)
    exec('ue_param id='..UEID..' ue_nr_')
   for gw_id = 1, 10 do
       exec('set_pdu_gateway id='..gw_id..' ue_nat_ip=72.23.0.'..UEID..' dl_nat_gw='..SERVER_IP..' ul_nat_gw='..SERVER_IP..'')
   end
end

